Use ASP.NET Core's `WebApplicationFactory<T>` to host your server in-process and drive MCP requests through its `HttpClient`:

```csharp
// MyMcpServerTests.cs
using Microsoft.AspNetCore.Mvc.Testing;
using System.Net.Http.Json;
using Xunit;

public class McpServerTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly HttpClient _client;

    public McpServerTests(WebApplicationFactory<Program> factory)
    {
        _client = factory.CreateClient();
    }

    [Fact]
    public async Task Initialize_ReturnsCapabilities()
    {
        var request = new
        {
            jsonrpc = "2.0",
            id = 1,
            method = "initialize",
            @params = new
            {
                protocolVersion = "2025-03-26",
                capabilities = new { },
                clientInfo = new { name = "test-client", version = "1.0" }
            }
        };

        var response = await _client.PostAsJsonAsync("/mcp", request);

        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        Assert.Equal("2025-03-26",
            body.GetProperty("result")
                .GetProperty("protocolVersion")
                .GetString());
    }

    [Fact]
    public async Task ToolsList_ReturnsRegisteredTools()
    {
        var request = new
        {
            jsonrpc = "2.0",
            id = 2,
            method = "tools/list",
            @params = new { }
        };

        var response = await _client.PostAsJsonAsync("/mcp", request);

        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        var tools = body.GetProperty("result").GetProperty("tools");
        Assert.True(tools.GetArrayLength() > 0);
    }
}
```

**Key points:**

- **`WebApplicationFactory<Program>`** boots your real DI container, middleware, and routing in-memory — no TCP port needed.
- Override services for isolation (e.g., mock databases) via `factory.WithWebApplicationFactory(b => b.ConfigureServices(...))`.
- If your server uses **SSE streaming** (`text/event-stream`), read the response stream incrementally:

```csharp
using var stream = await response.Content.ReadAsStreamAsync();
using var reader = new StreamReader(stream);
var line = await reader.ReadLineAsync(); // parse SSE frames
```

- If you use the **Streamable HTTP** transport with session headers, capture the `Mcp-Session-Id` from the initialize response and attach it to subsequent requests.

This gives you full protocol-level coverage (JSON-RPC framing, content negotiation, error codes) with fast, deterministic, in-process execution.
